const markBillingProviderEventDead = `-- name: MarkBillingProviderEventDead :exec

UPDATE billing_provider_events SET processed_at = $1::timestamptz, error = $2
WHERE id = $3
`

type MarkBillingProviderEventDeadParams struct {
	Now   time.Time
	Error string
	ID    uuid.UUID
}

// Billing HTTP, webhook inbox, reconciliation and mail (T5: internal/billing/http,
// internal/billing/inbox). Same rules as billing.sql: money mutations run in a transaction that
// locked the account first; time comes from billing.Clock as sqlc.arg('now').
// An event that will never be processed (orphan, mismatch, too many attempts): kept with its
// error for the admin event list, not claimed again.
func (q *Queries) MarkBillingProviderEventDead(ctx context.Context, arg MarkBillingProviderEventDeadParams) error {
	_, err := q.db.Exec(ctx, markBillingProviderEventDead, arg.Now, arg.Error, arg.ID)
	return err
}

